# ----------------------------- Database -----------------------------
def db():
    con = sqlite3.connect(DB_FILE, timeout=10)
    con.execute("PRAGMA journal_mode=WAL")
    return con

def init_db():
    con=db(); cur=con.cursor()
    cur.execute("""CREATE TABLE IF NOT EXISTS quiz_attempts(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        player TEXT NOT NULL, category TEXT NOT NULL, mode TEXT NOT NULL,
        score INTEGER NOT NULL, total INTEGER NOT NULL, percentage REAL NOT NULL,
        played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS multiplayer_matches(
        id INTEGER PRIMARY KEY AUTOINCREMENT, room_code TEXT NOT NULL,
        player1 TEXT NOT NULL, player2 TEXT NOT NULL, category TEXT NOT NULL,
        mode TEXT NOT NULL, score1 INTEGER NOT NULL, score2 INTEGER NOT NULL,
        played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)""")
    con.commit(); con.close()

def save_attempt(player, category, mode, score, total):
    con=db(); con.execute("INSERT INTO quiz_attempts(player,category,mode,score,total,percentage) VALUES(?,?,?,?,?,?)",
        (player,category,mode,score,total,(score/total*100 if total else 0))); con.commit(); con.close()

def history(limit=50):
    con=db(); rows=con.execute("SELECT player,category,mode,score,total,percentage,played_at FROM quiz_attempts ORDER BY id DESC LIMIT ?",(limit,)).fetchall(); con.close()
    return [dict(player=r[0],category=r[1],mode=r[2],score=r[3],total=r[4],percentage=round(r[5],1),played_at=r[6]) for r in rows]

# ----------------------------- Quiz data -----------------------------
def build_questions(category, count):
    rows=QUESTION_DATA[category]
    count=max(1,min(int(count),len(rows)))
    answers=list(dict.fromkeys(a for _,a in rows))
    chosen=random.sample(rows,count)
    result=[]
    for i,(q,a) in enumerate(chosen):
        pool=[x for x in answers if x!=a]
        opts=[a]+random.sample(pool,3)
        random.shuffle(opts)
        result.append({"question":q,"answer":a,"options":opts,"difficulty":["Easy","Medium","Hard"][i%3]})
    return result

def safe_name(x):
    x=str(x or "Player").strip()[:24]
    return x or "Player"

def safe_count(x):
    try: n=int(x)
    except: n=10
    return max(1,min(100,n))

# ----------------------------- Live VS Friend rooms -----------------------------
ROOMS={}
ROOM_LOCK=threading.RLock()

def new_code():
    alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    while True:
        code=''.join(secrets.choice(alphabet) for _ in range(6))
        if code not in ROOMS: return code

def room_public(room, token=None):
    p=list(room['players'].values())
    me=room['players'].get(token) if token else None
    opp=next((x for x in p if not token or x['token']!=token),None)
    idx=room['index']
    q=room['questions'][idx] if idx < len(room['questions']) else None
    return {
        'code':room['code'],'status':room['status'],'category':room['category'],'mode':room['mode'],
        'count':len(room['questions']),'index':idx,'time_limit':room['time_limit'],
        'round_started':room['round_started'],'round_left':max(0,int(room['time_limit']-(time.time()-room['round_started']))) if room['status']=='playing' else 0,
        'me':({'name':me['name'],'score':me['score'],'answered':me['answered'].get(idx)} if me else None),
        'opponent':({'name':opp['name'],'score':opp['score'],'answered':(idx in opp['answered'])} if opp else None),
        'players':[{'name':x['name'],'score':x['score']} for x in p],
        'question':({'question':q['question'],'options':q['options'],'difficulty':q['difficulty']} if q and room['status']=='playing' else None),
        'winner':room.get('winner'),'finished_scores':room.get('finished_scores')
    }

def maybe_advance(room):
    if room['status']!='playing': return
    idx=room['index']; now=time.time()
    players=list(room['players'].values())
    if len(players)<2: return
    all_answered=all(idx in p['answered'] for p in players)
    timed_out=(now-room['round_started'])>=room['time_limit']
    if not (all_answered or timed_out): return
    # unanswered is wrong; correct answers are already scored when submitted
    if idx+1>=len(room['questions']):
        room['status']='finished'
        room['finished_scores']={p['name']:p['score'] for p in players}
        vals=sorted([(p['score'],p['token'],p['name']) for p in players], reverse=True)
        room['winner']='Tie' if vals[0][0]==vals[1][0] else vals[0][2]
        con=db(); con.execute("INSERT INTO multiplayer_matches(room_code,player1,player2,category,mode,score1,score2) VALUES(?,?,?,?,?,?,?)",
            (room['code'],players[0]['name'],players[1]['name'],room['category'],room['mode'],players[0]['score'],players[1]['score'])); con.commit(); con.close()
    else:
        room['index']+=1; room['round_started']=time.time()

def cleanup_rooms():
    while True:
        time.sleep(60)
        with ROOM_LOCK:
            cutoff=time.time()-ROOM_TTL
            for c in list(ROOMS):
                if ROOMS[c]['created']<cutoff: ROOMS.pop(c,None)

